package com.offlinetranslator.ai
sealed class TranslationException(message:String,cause:Throwable?=null):Exception(message,cause){class ModelNotFound:TranslationException("CTranslate2 model is not installed");class TokenizerNotFound:TranslationException("SentencePiece tokenizer is not installed");class NativeUnavailable(cause:Throwable):TranslationException("CTranslate2 native library failed to load",cause);class InferenceFailed(cause:Throwable):TranslationException("CTranslate2 inference failed",cause);class OutOfMemory:TranslationException("Insufficient memory for translation")}
